-- ---------------------------------------------------------------------------
-- POSTFLIGHT: hard guards (any violation → COMMIT below never runs → rollback)
-- ---------------------------------------------------------------------------
do $post014$
declare
  v_rest integer; v_places integer; v_unver integer; v_coords integer;
  v_nolink integer; v_nosrc integer; v_temple integer;
begin
  select count(*) into v_rest from public.restaurants where source = 'tptm-master-b14';
  if v_rest <> 22 then
    raise exception 'POSTFLIGHT FAIL: expected 22 batch-014 restaurant rows, found %.', v_rest;
  end if;
  select count(*) into v_places from public.places where source = 'tptm-master-b14';
  if v_places <> 5 then
    raise exception 'POSTFLIGHT FAIL: expected 5 batch-014 place rows, found %.', v_places;
  end if;

  select count(*) into v_unver from public.restaurants where source = 'tptm-master-b14' and verification_status <> 'unverified';
  v_unver := v_unver + (select count(*) from public.places where source = 'tptm-master-b14' and verification_status <> 'unverified');
  if v_unver <> 0 then
    raise exception 'POSTFLIGHT FAIL: % rows are not unverified — an import never self-verifies.', v_unver;
  end if;

  select count(*) into v_coords from public.restaurants where source = 'tptm-master-b14' and (latitude is not null or longitude is not null);
  v_coords := v_coords + (select count(*) from public.places where source = 'tptm-master-b14' and latitude is not null);
  if v_coords <> 0 then
    raise exception 'POSTFLIGHT FAIL: expected exactly 0 evidenced coordinate row, found %.', v_coords;
  end if;

  select count(*) into v_nolink from public.places where source = 'tptm-master-b14' and destination_id is null;
  if v_nolink <> 0 then
    raise exception 'POSTFLIGHT FAIL: % place rows missing destination linkage.', v_nolink;
  end if;

  select count(*) into v_nosrc from public.places where source = 'tptm-master-b14' and (source_url is null or source_url = '');
  if v_nosrc <> 0 then
    raise exception 'POSTFLIGHT FAIL: % place rows missing source_url.', v_nosrc;
  end if;

  select count(*) filter (where place_type = 'temple') into v_temple
    from public.places where source = 'tptm-master-b14';
  if v_temple <> 5 then
    raise exception 'POSTFLIGHT FAIL: place_type distribution drifted (temple=%; expected 5).', v_temple;
  end if;
  raise notice 'POSTFLIGHT OK: 27 rows verified (22 restaurants + 5 places; temple 5).';
end
$post014$;

